//! The Omafile's catalog: which snapshot keys leave the machine, which may come back, and what
//! changes when they do, as `services/Settings.js`'s `settingsCatalog()` and `settingsSections()`
//! give them, copied from the JavaScript: `tests/omafile_parity.rs` holds the two equal, so a
//! change to either fails until the other follows.

/// One setting an Omafile carries (`entry(...)`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Item {
    pub key: &'static str,
    pub section: &'static str,
    pub label: &'static str,
    /// `look`, `behavior`, `identity` or `system`.
    pub tier: &'static str,
    /// `scalar` or `list`.
    pub kind: &'static str,
    /// `string`, `integer`, `number`, `boolean` or `list`.
    pub ty: &'static str,
    /// The snapshot key listing what this machine has to choose from, if any.
    pub options: &'static str,
    /// The values the writer takes, if fixed.
    pub choices: Option<&'static [&'static str]>,
    pub format: &'static str,
    pub host_bound: bool,
    pub needs_root: bool,
    pub extra_confirm: bool,
    pub consequence: &'static str,
    pub importable: bool,
}

/// A section of the file: its id, its heading and its note.
pub type Section = (&'static str, &'static str, &'static str);

